import Root from "./1Adding Interactivity/2StateasSnapshot"
import { NotShared, Shared, UsingImmer } from "./1Adding Interactivity/5zCoreCocept"
import Sub from "./subReLearn"
import "./ReLearn.css"
import {useState} from "react"

export default function () {
  const [obj, setObj] = useState({a:"",b:"",c:{a:"",b:""}})
  return (
    <>
    <button onClick={() => {setObj({...obj,a: "anjass"})}}>click</button> <br/>
    <button onClick={() => {setObj({...obj,b:"anjass"})}}>click</button> <br/>
    <button onClick={() => {setObj({...obj,c: {...obj.c, a:"uwu"}})}}>click</button> <br/>
    <button onClick={() => {setObj({...obj,c: {...obj.c, a:"uwu"}})}}>click</button>
    <p>
      
      {obj.a} <br/>
      {obj.b} <br/>
      {obj.c.a} <br/>
      {obj.c.d} <br/>
    </p>
    </>
  );
}


// http://localhost:3000
